import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"升","description":"焦氏易林注 - 升","frontmatter":{"title":"升","description":"焦氏易林注 - 升"},"headers":[],"relativePath":"classics/jiaoyilin/046.md","filePath":"classics/jiaoyilin/046.md"}'),l={name:"classics/jiaoyilin/046.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="升" tabindex="-1">升 <a class="header-anchor" href="#升" aria-label="Permalink to “升”">​</a></h1><h3 id="升-1" tabindex="-1">升 <a class="header-anchor" href="#升-1" aria-label="Permalink to “升”">​</a></h3><h3 id="升之乾" tabindex="-1">升之乾 <a class="header-anchor" href="#升之乾" aria-label="Permalink to “升之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>白鹿鳴呦，呼其老小。喜彼茂草，樂我君子。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《升》象。震為白、為鹿、為鳴呼，坤老，兌小，震為喜樂、為茂草，伏艮為君子。○小，汲古作少，依宋元本。</p><h3 id="升之坤" tabindex="-1">升之坤 <a class="header-anchor" href="#升之坤" aria-label="Permalink to “升之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>百裡南行，雖微復明。去虞適秦，為穆國卿。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>百裡奚仕虞，後適秦，相秦穆公。坤為百裡，遇卦升震為南行、為驩虞，兌為秦，坤為國。○復，宋元本作得，依汲古。</p><h3 id="升之屯" tabindex="-1">升之屯 <a class="header-anchor" href="#升之屯" aria-label="Permalink to “升之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>王孫宜家，張名益有。龍子善行，西得大壽。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為王，艮為孫、為家、為名，震為張，故曰張名，言張大其名也。震為龍子，艮為壽，坎居西，故曰西得大壽。</p><h3 id="升之蒙" tabindex="-1">升之蒙 <a class="header-anchor" href="#升之蒙" aria-label="Permalink to “升之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>畫龍頭頸，文章不成。甘言善語，譎詞無名。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《賁》。二三句宋元本作&quot;所求不得，失利後時&quot;，今依汲古。</p><h3 id="升之需" tabindex="-1">升之需 <a class="header-anchor" href="#升之需" aria-label="Permalink to “升之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>商子無良，相怨一方。引鬬交爭，咎以自當。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>商鞅變法，人民怨恨。鬬，宋元本作剛，依汲古。此用遇卦《升》象。震為商旅、為子，坤惡，故曰無良。坤為怨、為方，兌為剛魯，故爭鬬，正反兌，故曰交爭。咎以自當者，言商鞅亡至客舍，無驗，舍人曰：商君之法，舍人無驗者，坐之。而自當其咎也。</p><h3 id="升之訟" tabindex="-1">升之訟 <a class="header-anchor" href="#升之訟" aria-label="Permalink to “升之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>衰老困極，無齒不食。痔病痏瘵，就長夜室。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為老，坎為困，兌為齒，兌覆，故曰無齒，故曰不食。痔，《說文》：後病也。二至五巽，巽下腐，有類於痔漏。痏，創也。瘵，癆病也。坎為勞、為夜、為室。○痏，宋元本作痟，依汲古。末句依《坤》之《隨》校，各本皆作就陰為室。就長夜室，言死也。</p><h3 id="升之師" tabindex="-1">升之師 <a class="header-anchor" href="#升之師" aria-label="Permalink to “升之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>鳶生會稽，稍巨能飛。翱翔桂林，為眾鳥雄。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為鳶、為生，坤聚，故曰會稽。震為飛、為桂林、為鳥，坤為眾，故曰眾鳥。○鳶，汲古作鴛，依宋元本。</p><h3 id="升之比" tabindex="-1">升之比 <a class="header-anchor" href="#升之比" aria-label="Permalink to “升之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>安平不傾，載福長生，君子以寧。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎為平，艮為安、為君子。</p><h3 id="升之小畜" tabindex="-1">升之小畜 <a class="header-anchor" href="#升之小畜" aria-label="Permalink to “升之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>牛驥同槽，郭氏以亡。國破為墟，君奔走逃。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《晉》。</p><h3 id="升之履" tabindex="-1">升之履 <a class="header-anchor" href="#升之履" aria-label="Permalink to “升之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>日中明德，盛興兩國。仁聖會遇，君受其福，臣多榮祿。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>離為甘、為明，伏坤為國，坤數二，故曰兩國。乾為仁聖、為君，伏艮為臣。</p><h3 id="升之泰" tabindex="-1">升之泰 <a class="header-anchor" href="#升之泰" aria-label="Permalink to “升之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>公劉之居，太王所業。可以長生，拜受福爵。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾君，故曰公劉、曰太王。震為長生，伏艮為拜、為爵。公劉，周祖，言公劉遷邠，太王因以興起也。</p><h3 id="升之否" tabindex="-1">升之否 <a class="header-anchor" href="#升之否" aria-label="Permalink to “升之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>時凋歲霜，君子疾病。宋女無辜，鄭受其殃。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為時，巽隕落，故曰時凋。坤為歲、為霜、為疾病，艮為君子、為宋，與坤連體，故曰宋女。《說文》：&quot;宋，以木架屋也&quot;，故艮形象之。坤為鄭，鄭，地町町然平也，坤形象之。坤為殃，故曰鄭受其殃。按：《左傳桓十一年》：&quot;宋雍氏女於鄭莊公曰姞，生厲公，雍氏宗有寵於宋莊公，故誘祭仲而執之，曰：不立突，將死。亦執厲公而求賂，自是鄭公子更相立，亂屢起。&quot;故曰鄭受其殃，然此自雍氏禍鄭，宋女何辜哉。○霜，汲古作寂，依宋元本。宋，宋元本訛宗，依汲古。</p><h3 id="升之同人" tabindex="-1">升之同人 <a class="header-anchor" href="#升之同人" aria-label="Permalink to “升之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>濟河逾厄，脫母怵惕。四叔為衛，使惠不廢。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>九家及荀爽皆以乾為河，伏坎為厄，坤為母，坤伏，故曰脫母。乾為惕，故怵惕。脫母字恐有訛。○叔，汲古作序，依宋元本。四叔或指四皓輔惠帝事。</p><h3 id="升之大有" tabindex="-1">升之大有 <a class="header-anchor" href="#升之大有" aria-label="Permalink to “升之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>缺破不完，殘瘵側偏。公孫幽遏，跛倚後門。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>兌為缺破，伏坎為勞、為瘵、為幽遏、為跛倚，乾為門，事未詳。○跛，元本作跂，依宋本、汲古。瘵，汲古訛際，依宋元本。</p><h3 id="升之謙" tabindex="-1">升之謙 <a class="header-anchor" href="#升之謙" aria-label="Permalink to “升之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>延頸遠望，眯為目病。不見叔姬，使我心憂。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為頸、為望，伏乾，故曰遠望。艮為目，坎棘入居目中，故曰眯為目病。眯，《說文》：&quot;物入目中也。&quot;正坎象也。艮為叔，震為姬，坎隱，故不見。震為伯，坎為心憂。○眯，宋本、汲古作昧，依元本。</p><h3 id="升之豫" tabindex="-1">升之豫 <a class="header-anchor" href="#升之豫" aria-label="Permalink to “升之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>上無飛鳥，下無走獸。擾亂未清，民勞於事。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為鳥，為飛，在上，艮為獸，在下，中互坎隱，故曰無。震為擾，坤為亂，坎黑，故曰未清。坎為勞，坤為民、為事。</p><h3 id="升之隨" tabindex="-1">升之隨 <a class="header-anchor" href="#升之隨" aria-label="Permalink to “升之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>久陰霖雨，塗行泥潦。商人休止，市空無寶。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》《大過》。○商，汲古作民，依宋元本。市，元本訛布，依宋本、汲古。寶，各本作有，依《革》之《睽》校。</p><h3 id="升之蠱" tabindex="-1">升之蠱 <a class="header-anchor" href="#升之蠱" aria-label="Permalink to “升之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>盲者目張，跛倚起行。瞻望日月，與主相迎。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互大離故曰盲，言目無睛也。震為足，兌折，故足跛。艮為瞻望、為日，兌為月，故曰瞻望日月。震為主，三至上正反震，故曰與主相迎。○目張，宋元本作張目，主作王，均依汲古。</p><h3 id="升之臨" tabindex="-1">升之臨 <a class="header-anchor" href="#升之臨" aria-label="Permalink to “升之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>據鬥運樞，高步六虛。權既在手，寰宇可驅。國大無憂，與樂並居。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通《遯》。艮為星、為手，故曰據鬥運樞。巽為高，本卦震為步，坤為虛，乾數六，故曰六虛。系詞&quot;變動不居，周流六虛&quot;，虞翻雲：六虛，六位也。巽為權，艮為手，坤為寰宇、為國、為憂，震解故無憂。○汲古樞下作&quot;順天無憂，與樂並居，萬代歡娛&quot;，依宋元本。</p><h3 id="升之觀" tabindex="-1">升之觀 <a class="header-anchor" href="#升之觀" aria-label="Permalink to “升之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>稼穡不偏，重適不傾。巧言賊忠，傷我申生。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為稼穡，伏震為適，子坤為重，坤厚載物，故不傾。巽為賊，伏震為言，兌為言，乾亦為言，言多，故曰巧言賊忠。震為生，兌毀，故傷我申生。○適，宋元本作過，非，依汲古。申生，晉太子，為驪姬讒死。</p><h3 id="升之噬嗑" tabindex="-1">升之噬嗑 <a class="header-anchor" href="#升之噬嗑" aria-label="Permalink to “升之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>金城鐵郭，上下同力。政平民親，寇不敢賊。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為城郭、為金鐵，艮上震下，坎為平，故上下同力。坎為眾、為民，又為寇賊。○親，汲古作歡，依宋元本。</p><h3 id="升之賁" tabindex="-1">升之賁 <a class="header-anchor" href="#升之賁" aria-label="Permalink to “升之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>日鏡不明，冬災大傷。盜華失實，十年消亡。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>離日為鏡，坎黑，故不明。坎為冬、為災、為盜，震為華，故曰盜華，言不時也。春秋十二月書桃李華是也。艮為果實，坎失，故曰失實。震為年，伏兌，數十，故曰十年。○日，宋元本作目，依汲古。</p><h3 id="升之剝" tabindex="-1">升之剝 <a class="header-anchor" href="#升之剝" aria-label="Permalink to “升之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>鰥寡孤獨，命祿苦薄。入室無妻，武子悲哀。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮鰥坤寡，艮為室，兌為艮妻，兌伏，故曰無妻。震為武、為子，震覆，故悲哀。坤為悲也。武子，崔杼，杼娶棠薑，佔得《困六三》&quot;入其室，不見其妻&quot;，見《左傳》。</p><h3 id="升之復" tabindex="-1">升之復 <a class="header-anchor" href="#升之復" aria-label="Permalink to “升之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>飲酒醉酗，跳起爭鬬。伯傷叔僵，東家治喪。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《蒙》。○酗，各本皆作飽，非，依《益》之《蒙》校。</p><h3 id="升之無妄" tabindex="-1">升之無妄 <a class="header-anchor" href="#升之無妄" aria-label="Permalink to “升之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>介紹微子，使君不殆。二國合歡，燕齊以安。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為子，艮小，故曰微子，正反震，故曰介紹。《禮聘儀》：&quot;介紹而傳命。&quot;又《戰國策》：&quot;請為紹介&quot;註：相佐助也。震為君，艮為國，正反艮相對，故曰合。正反震相對，故曰合歡。艮為燕、為安，巽為齊。殆，音以，與子韻。</p><h3 id="升之大畜" tabindex="-1">升之大畜 <a class="header-anchor" href="#升之大畜" aria-label="Permalink to “升之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>牽牛系尾，詘折幾死。雕世無仁，不知所比。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>通《萃》。艮為牛，艮手為牽，艮為尾，巽為系，前牽後系，故r折幾死。兌為折，坤為死、為世、為敝，故曰雕世。《論語》：&quot;歲寒然後知松柏之後雕&quot;。雕，殘也，零落也。○牛，汲古作頸，依宋元本。雕，元本作雕，依宋本、汲古，然恐仍訛。</p><h3 id="升之頤" tabindex="-1">升之頤 <a class="header-anchor" href="#升之頤" aria-label="Permalink to “升之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>東龍冤毒，不知所觸。南北困窮，王子危急。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為東，坤為毒，艮為角、為觸，正反艮，故曰不知所觸。震為南，坤為北、為困窮，震為王、為子，坤為危。○冤，汲古作究，非，依宋元本。王子似指王子帶，後為晉文所殺。</p><h3 id="升之大過" tabindex="-1">升之大過 <a class="header-anchor" href="#升之大過" aria-label="Permalink to “升之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>疾貧王孫，北陸無輝。祿命苦薄，兩守孤門。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。坤為疾、為貧，震為王，艮為孫，故曰疾貧王孫。坤為北，故曰北陸。坤黑，故無輝。巽為命，乾為祿，故曰祿命。坤為苦薄，兌卦數二，故曰兩。乾為門，巽為寡，故曰孤門。○輝，宋元本作禪，守作事，均依汲古。陸，汲古作極，依宋元本。</p><h3 id="升之坎" tabindex="-1">升之坎 <a class="header-anchor" href="#升之坎" aria-label="Permalink to “升之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>公孫駕驪，載遊東齊。延陵說產，遺季紵衣。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>震為公，艮為孫，震馬，故曰駕驪。震為東，伏巽為齊，艮為魯，重艮，故曰延陵。又艮為季子也。震為悅、為紵衣，事詳《乾》之《益》。○驪，宋元本訛釃，汲古作車，依局本。</p><h3 id="升之離" tabindex="-1">升之離 <a class="header-anchor" href="#升之離" aria-label="Permalink to “升之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>王良善御，伯樂知馬。文王東獵，獲嘉賢士。開福佑周，發旦興起。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>震為王，艮為良，震為馬、為伯、為樂、為王、為福、為周、為士、為旦，離為文，震為東、為獵，全用伏象。○第四句宋元作獲喜聖事，周發旦作賢周發，均依汲古。下四句言文王因獵獲薑尚，輔文武成王業。發，武王名；旦，周公名。</p><h3 id="升之鹹" tabindex="-1">升之鹹 <a class="header-anchor" href="#升之鹹" aria-label="Permalink to “升之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>日月不居，重耳趨舍。遊齊入秦，晉國是霸。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮乾皆為日，兌為月，不居者，不息也。兌為耳，伏坤為重，故曰重耳。艮為舍，巽為齊，兌為秦，巽入，故曰入秦。艮為國，伏震為晉、為霸。</p><h3 id="升之恆" tabindex="-1">升之恆 <a class="header-anchor" href="#升之恆" aria-label="Permalink to “升之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>假文翰翼，隨風偕北。至虞夏國，與舜相得。年歲大樂，邑無盜賊。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為羽翰，伏坤，故曰文翰。文翰，鳥也。《周書》：&quot;蜀人以文翰&quot;，文翰者，似皋雞。巽風，坤北，故曰隨風偕北。伏坤為國，震為帝，故曰舜。坤為年歲、為邑，巽為盜賊，乾無也。○偕，汲古訛背，得訛傳，依宋元本。</p><h3 id="升之遯" tabindex="-1">升之遯 <a class="header-anchor" href="#升之遯" aria-label="Permalink to “升之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>南行北走，延頸望食。舉正失利，累我子孫。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為南、為行，伏坤為北，震為走，故曰南行北走。艮為頸、為望，伏兌為食，巽為利，艮止，故失利。艮為我、為孫，伏震為子。○北走，宋元本作無遯，望作後，均依汲古。止，汲古作口，依宋元本。第四句宋本作累為子孫，元本作累為我孫，依汲古。</p><h3 id="升之大壯" tabindex="-1">升之大壯 <a class="header-anchor" href="#升之大壯" aria-label="Permalink to “升之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>開市作喜，建造利事。平準貨寶，海內殷富。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震喜，伏巽為市、為利，震為玉，乾亦為金玉，故曰貨寶。乾為富、為海。平準者，《史記索隱》雲：大司農有平準令丞，貴則糶之，賤則買之，平賦以相準，輸於京師。○市，宋元本作元，依汲古。</p><h3 id="升之晉" tabindex="-1">升之晉 <a class="header-anchor" href="#升之晉" aria-label="Permalink to “升之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>三犬俱走，鬬於谷口。白者不勝，死於阪下。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮數三，故曰三犬。艮為谷，震為白，震覆，故死於阪下。艮為阪，坤為死也。○阪，宋元本作阪，依汲古。</p><h3 id="升之明夷" tabindex="-1">升之明夷 <a class="header-anchor" href="#升之明夷" aria-label="Permalink to “升之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>驕胡犬形，造惡作兇。無所能成，還自滅身。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為胡，覆艮為犬，而與坤連體，故曰驕胡犬形。坤為兇惡、為喪亡，故無成。坤為身，坤死，故曰滅身。○犬形，宋元本作大彤，依汲古。</p><h3 id="升之家人" tabindex="-1">升之家人 <a class="header-anchor" href="#升之家人" aria-label="Permalink to “升之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>跪拜贊詞，無益於尤。大夫頑囂，使我心憂。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>《新序》：&quot;晉中行寅將亡，召其太祝而欲加罪焉，曰：子為我祝而使我亡國，何也。曰：子不務德而厚斂於民，則民怨。一人祝之，一國詛之，國亡，不亦宜乎&quot;。</p><h3 id="升之睽" tabindex="-1">升之睽 <a class="header-anchor" href="#升之睽" aria-label="Permalink to “升之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>辰次降婁，王駕巡狩。廣佑施惠，萬國鹹喜。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《大畜》。</p><h3 id="升之蹇" tabindex="-1">升之蹇 <a class="header-anchor" href="#升之蹇" aria-label="Permalink to “升之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>牽羭上樓，與福俱遊。躬勞治國，安樂無憂。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>○羭，汲古作瑜，依宋元本。遊，宋元作居，依汲古。此林或用升象。兌為羭，坤為樓，他林或言樓皆坤象，互震為福、為遊。坤為躬、為國，坤役萬物，故勞。坤為憂，震樂，故無憂。</p><h3 id="升之解" tabindex="-1">升之解 <a class="header-anchor" href="#升之解" aria-label="Permalink to “升之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>白鳥銜餌，鳴呼其子。旋枝張翅，來從其母。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《震》。旋枝，宋元本作挾施，汲古作投杖，依《晉》之《震》校。</p><h3 id="升之損" tabindex="-1">升之損 <a class="header-anchor" href="#升之損" aria-label="Permalink to “升之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>盲瞽獨宿，莫與共食。老窮於人，病在心腹。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>互大離若目之無睛，故曰盲瞽。坤為寡、為宿，故曰獨宿。兌為食，獨則無與共也。坤為老、為窮、為病、為心、為腹。於，依也。震為人，言窮老依人也。○瞽，汲古作聾，依宋元本。</p><h3 id="升之益" tabindex="-1">升之益 <a class="header-anchor" href="#升之益" aria-label="Permalink to “升之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>登木出淵，稍上升天。明德孔聖，白日載榮。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>震為木、為登，坤為淵，故曰出淵。艮為天，與震對，故曰稍上升天。艮為明，震為孔、為德，伏乾為聖，故曰孔聖。艮為日，震為白、為榮，震車，故曰載榮。○載榮下汲古多寵祿再熒四字，依宋元本刪。</p><h3 id="升之夬" tabindex="-1">升之夬 <a class="header-anchor" href="#升之夬" aria-label="Permalink to “升之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>彭離濟東，遷廢上庸。狠戾無節，失其寵功。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>元刊註：彭越後赦，遷蜀。上庸，蜀也。按：武帝元鼎元年，濟東王彭離有罪，廢，徙上庸，似指此事。○廢，汲古作之，狠作狼，均依宋本。</p><h3 id="升之姤" tabindex="-1">升之姤 <a class="header-anchor" href="#升之姤" aria-label="Permalink to “升之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>贊揚上舞，神明正氣。禹拜受福，君施我德。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>伏震為言，故曰贊揚。震為舞、為神、為君，故曰禹。又為福為德，古臣謁君須贊名拜舞。艮為首，艮覆，首至地，故曰禹拜受福。○正，宋元作生，禹拜作拜禹，施作使，均依汲古，惟汲古多居則厚祿四字，依宋元本刪。</p><h3 id="升之萃" tabindex="-1">升之萃 <a class="header-anchor" href="#升之萃" aria-label="Permalink to “升之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>從首至足，部分為六。室家離散，逐南乞食。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>通《大畜》。乾為首，艮為肩背，震為足，乾數六，言首、肩、胸、腹、股、足共六部也。艮為室家，三上正反艮，故曰離散。乾南，震逐，兌食，艮求，故曰逐南乞食。三四句似指伍子胥事。</p><h3 id="升之升" tabindex="-1">升之升 <a class="header-anchor" href="#升之升" aria-label="Permalink to “升之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>禹鑿龍門，通利水源。東註滄海，人民得安。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《豫》。○源，宋元本作泉，末句作民得安全，均依汲古。</p><h3 id="升之困" tabindex="-1">升之困 <a class="header-anchor" href="#升之困" aria-label="Permalink to “升之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>民迷失道，亂我統紀。空使乾華，實無所有。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。坎為眾、為民，坎隱，故迷而失道。震為道，正反震，故曰亂我統紀。震為華，離火下熇，故曰乾華。艮為實，華萎故無實。○華，宋元本訛革，依汲古。實，汲古訛賓，依宋元本。又汲古末有先憂後樂四字，依宋元本。</p><h3 id="升之井" tabindex="-1">升之井 <a class="header-anchor" href="#升之井" aria-label="Permalink to “升之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>刻畫為飾，嫫母無益。毛嬙西施，求事必得。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。艮手為刻畫，離為惡人，故曰嫫母。震為毛羽，坎為西，而兌為媚好，故曰毛嬙西施，皆古美人名。艮為求。首二句言嫫母本醜，雖飾無益。○第二句依宋元本增加，汲古無。</p><h3 id="升之鼎" tabindex="-1">升之鼎 <a class="header-anchor" href="#升之鼎" aria-label="Permalink to “升之鼎”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>衣裳顛倒，為王來呼。成就東周，封受大侯。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>《詩齊風》：&quot;顛倒衣裳，顛之倒之，自公召之。&quot;毛謂剌無節，林意似指呂伋父子為卿，王朝在公情狀。鼎通屯。震為衣裳，正反震，故顛倒衣裳。震為呼、為王，震為東、為諸侯，坤為國。○周，汲古作國，依宋元本。侯，宋元本作休，非，依汲古。</p><h3 id="升之震" tabindex="-1">升之震 <a class="header-anchor" href="#升之震" aria-label="Permalink to “升之震”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>當變立權，摘解患難。渙然冰釋，六國以寧。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>伏巽為權。互坎為患難。震為解，故曰渙然冰釋，坎為冰也。艮為國，坎數六，故曰六國。艮安，故寧。此指蘇秦說六國合從事。</p><h3 id="升之艮" tabindex="-1">升之艮 <a class="header-anchor" href="#升之艮" aria-label="Permalink to “升之艮”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>西戎獯鬻，病於我國。杖策之岐，以保乾德。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>互坎為西，艮為狗，故曰犬戎獯鬻。坎為病，艮為國，坎為杖策、為西，艮山，故曰杖策之岐。艮居西北，乾地，故曰以保乾德。顧千里雲：扶陝之岐當作杖策之岐，尚書大傳：遂杖策而去，過梁山邑岐山。陳樸園《齊詩考》引亦作杖策，故從之。○第三句宋元本作扶陝之岐，汲古作扶陽之正，依顧陳校。又汲古多終無患或四字，宋元無。</p><h3 id="升之漸" tabindex="-1">升之漸 <a class="header-anchor" href="#升之漸" aria-label="Permalink to “升之漸”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>南行逐羊，予利喜亡。陰孽為病，復返其邦。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>伏震為羊、為南、為行、為子，巽為利，坎為陰孽、為病，艮為邦。○予疑為好之形訛字，汲古作子，猶存其半。</p><h3 id="升之歸妹" tabindex="-1">升之歸妹 <a class="header-anchor" href="#升之歸妹" aria-label="Permalink to “升之歸妹”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>遊戲仁德，日益有福。兇言不至，妖孽滅息。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>震為仁德、為遊戲、為福，離日，故曰日益有福。震為言，坎為兇、為妖孽。</p><h3 id="升之豐" tabindex="-1">升之豐 <a class="header-anchor" href="#升之豐" aria-label="Permalink to “升之豐”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>春日新婚，就陽日溫。嘉樂萬歲，獲福大椿。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震春，離日，故曰陽、曰溫。震為嘉樂、為萬歲、為大椿，《莊子》：&quot;上古有大椿，以八千歲為春秋&quot;。○嘉，宋元本作喜，大椿作有年，均依汲古。</p><h3 id="升之旅" tabindex="-1">升之旅 <a class="header-anchor" href="#升之旅" aria-label="Permalink to “升之旅”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>陰升陽伏，鬼哭其室。相飾不食，安巢如棘。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《節》。陽皆在陰下，故曰陰升陽伏。坎為鬼，艮為室，震為笑，震之反則哭也。震為玄黃，故曰飾。正反震，故曰相飾。兌為食，艮止，故不食。艮為巢，坎為棘，艮坎連，故曰安巢如棘。○鬼哭，宋元本作舜失，依汲古。</p><h3 id="升之巽" tabindex="-1">升之巽 <a class="header-anchor" href="#升之巽" aria-label="Permalink to “升之巽”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>臣尊主卑，權威日衰。侵奪無光，三家逐公。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《震》。震為主，陰為臣，陽下陰上，故曰臣尊主卑。震為威，巽為權，互離為日，巽隕，故曰日衰。震為侵，艮手為奪，互坎故曰無光。艮為家，數三，故曰三家。震為公、為逐，故曰三家逐公。三家，孟孫、叔孫、季孫合謀逐昭公也。</p><h3 id="升之兌" tabindex="-1">升之兌 <a class="header-anchor" href="#升之兌" aria-label="Permalink to “升之兌”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>反言為賊，戎女生患。亂吾家國，父子相賊。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>互巽為賊，三至上正反兌為反言，兌為女，兌西，故曰戎女。《禹貢》西戎即敘。伏艮為家國，離為亂，伏震為父、為子，正反震相背，中隔坎，故曰相賊。此指晉驪姬讒申生獻公殺申生事，故曰戎女、曰父子相賊。</p><h3 id="升之渙" tabindex="-1">升之渙 <a class="header-anchor" href="#升之渙" aria-label="Permalink to “升之渙”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>迎福開戶，喜隨我後。康伯愷悌，治民以禮。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>震為開，艮為戶，震為喜、為後、為伯，坎為民。按：《史記》&quot;衛康叔卒，子康伯立&quot;註：康伯，名王孫牟。左傳所稱王孫牟父是也。按：《左傳》&quot;牟父與伯禽呂伋並事康王，必有賢德&quot;特其事，今皆亡耳。○隨，汲古作逐，後作後，均依宋元本。</p><h3 id="升之節" tabindex="-1">升之節 <a class="header-anchor" href="#升之節" aria-label="Permalink to “升之節”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>日就月將，昭明有功。靈臺觀賞，膠鼓作人。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮日兌月，艮為昭明、為靈臺，震為鼓，坎水，故曰膠鼓。震為作、為人，《廣韻》：&quot;膠，太學也。&quot;《禮王制》：&quot;養國老於東膠。&quot;《正字通》：&quot;東膠，周學名，即東序也。&quot;○觀，宋元本作歡，依汲古。人，汲古作仁，依宋元本。觀賞謂遊覽。鼓宜為庠。</p><h3 id="升之中孚" tabindex="-1">升之中孚 <a class="header-anchor" href="#升之中孚" aria-label="Permalink to “升之中孚”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>百草嘉卉，萌芽將出。昆蟲扶戶，陽明得所。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為百草、為嘉卉、為萌芽，巽為昆蟲，與艮連，故曰扶戶。此以震為荄茲，與趙賓讀同。</p><h3 id="升之小過" tabindex="-1">升之小過 <a class="header-anchor" href="#升之小過" aria-label="Permalink to “升之小過”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>天所佑助，萬國日有。福至禍去，壽命長久。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為天、為國、為日，震福，故曰萬國日有。艮為壽、為長久，巽為命。○第二句汲古無，第四句汲古作君主何憂，均依宋元本。</p><h3 id="升之既濟" tabindex="-1">升之既濟 <a class="header-anchor" href="#升之既濟" aria-label="Permalink to “升之既濟”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>窮夫失居，唯守弊廬。初憂中懼，惟曰兢兢，無悔無虞。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>通《未濟》。未濟男之窮，故曰窮夫失居。多用半象。○惟，宋本、汲古作終，依元本。弊，汲古作舊，依宋元本。</p><h3 id="升之未濟" tabindex="-1">升之未濟 <a class="header-anchor" href="#升之未濟" aria-label="Permalink to “升之未濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>賈玉得石，失其所欲。荷蕢擊磬，隱世無聲。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>震為玉、為蕢、為磬、為聲，艮石，皆半象。《論語》：&quot;子擊磬於衛，有荷蕢者曰有心哉，擊磬乎！&quot;按：荷蕢，隱士。</p>',317)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
